mask={(r,c) for r in range(15) for c in range(7) if a[r][c]==4}
shapes=[('1',2,5),('6',6,2),('2',2,2),('8a',1,4),('8b',1,4),('3',3,2),('0',1,1)]
# enumerate placements of solid rectangles and all non-overlap combinations
placements={}
for name,h,w in shapes:
    opts=[]
    for hh,ww in set([(h,w),(w,h)]):
        for r in range(15-hh+1):
            for c in range(7-ww+1):
                cells={(rr,cc) for rr in range(r,r+hh) for cc in range(c,c+ww)}
                if cells<=mask: opts.append((r,c,hh,ww,cells))
    placements[name]=opts
{k:len(v) for k,v in placements.items()}
